\documentclass{article}
\usepackage{amsmath}
\title{Notes on First-Order Linear Differential Equations}
\author{Course Notes, Week 5}
\date{}
\begin{document}
\maketitle
\section{The Standard Form}
A first-order linear ordinary differential equation can always be
written in the standard form
\begin{equation}
y' + p(x)\, y = q(x)
\end{equation}
where $p$ and $q$ are continuous functions on the interval of interest.
The equation is called homogeneous when $q(x) = 0$.
\section{Integrating Factor}
Multiplying both sides by the integrating factor $\mu(x) = e^{\int p(x)\,dx}$
turns the left-hand side into an exact derivative, and the solution
follows by integration:
\begin{align}
\bigl(e^{\int p}\, y\bigr)' &= e^{\int p}\, q \\
e^{\int p}\, y &= \int e^{\int p}\, q\, dx + C
\end{align}
Dividing through by the integrating factor gives the general solution.
\section{An Initial-Value Problem}
For the initial condition $y(x_0) = y_0$, the solution can be written
in closed form as
\begin{equation}
y(x) = y_0\, e^{-\int_{x_0}^{x} p(t)\,dt}
+ \int_{x_0}^{x} q(s)\, e^{-\int_{s}^{x} p(t)\,dt}\, ds
\end{equation}
which is sometimes called the variation-of-parameters formula.
\end{document}
